INSERT INTO core.source_registry (source_id, title_ko, title_en, provider, source_url, verification_level, provenance, fallback_strategy, notes) VALUES
  ('SRC_CORE_01', '송도 주요 장소 수기 정리', 'Curated Songdo landmark list', 'Team (manual curation)', NULL, 2, 'CURATED_MANUAL', 'Curated landmark fixture', 'Approximate centroids typed by hand; replace with geocoded official coordinates'),
  ('SRC_MOB_01', '인천광역시_버스정류장 정보', 'Incheon bus stop information', 'Incheon City', 'https://www.data.go.kr', 4, 'OFFICIAL_OPEN_DATA', 'Curated Songdo stop CSV fixture', 'Level from handbook; team must re-verify'),
  ('SRC_MOB_02', '인천광역시_버스노선 정보', 'Incheon bus route information', 'Incheon City', 'https://www.data.go.kr', 2, 'OFFICIAL_OPEN_DATA', 'Deterministic synthetic timetable', 'Level from handbook; team must re-verify'),
  ('SRC_MOB_03', '국토교통부_전국 버스정류장 위치정보', 'National bus stop locations', 'MOLIT', 'https://www.data.go.kr/data/15067528/fileData.do', 4, 'OFFICIAL_OPEN_DATA', 'fixtures/songdo_stops.csv (Songdo subset of the real file)', 'File dated 2026-11-09 downloaded 2026-11-14 (CP949, 227102 data rows, 9657 in Incheon); 513 Songdo stops confirmed; SHA-256 ed0d6524...d8f5ba'),
  ('SRC_MOB_SYN', '송도 모빌리티 합성 시간표 및 텔레메트리', 'Synthetic Songdo timetable and vehicle telemetry', 'Team (generator)', NULL, 4, 'SYNTHETIC_FIXTURE', 'Deterministic generator fixtures/seed_fixtures.py', 'Route patterns/trips/GPS are generated over real stop locations; not official data'),
  ('SRC_BLD_01', '국토교통부_건축물대장 정보', 'Building register information', 'MOLIT / VWorld', 'https://www.vworld.kr', 2, 'OFFICIAL_OPEN_DATA', 'Landmark building registry fixture', 'Level from handbook; team must re-verify'),
  ('SRC_BLD_SYN', '송도 스마트빌딩 합성 IoT 데이터', 'Synthetic smart-building IoT data', 'Team (generator)', NULL, 4, 'SYNTHETIC_FIXTURE', 'Deterministic generator fixtures/building_section.py', 'Interior spaces, devices, telemetry and maintenance are generated; not official data'),
  ('SRC_TOU_01', '전국관광지정보표준데이터', 'National tourist attraction standard data', 'MOIS / data.go.kr', 'https://www.data.go.kr', 4, 'OFFICIAL_OPEN_DATA', 'Songdo tourist centers fixture', 'Level from handbook; team must re-verify'),
  ('SRC_TOU_02', '인천관광 방문객 통계', 'Incheon tourism visitor statistics', 'Incheon Tourism', 'https://www.data.go.kr', 3, 'OFFICIAL_OPEN_DATA', 'Monthly visitor statistics fixture', 'Level from handbook; team must re-verify'),
  ('SRC_TOU_SYN', '송도 관광 합성 데이터', 'Synthetic Songdo tourism data', 'Team (generator)', NULL, 4, 'SYNTHETIC_FIXTURE', 'Deterministic generator fixtures/tourism_section.py', 'Real venue names; hours, accessibility, events and ALL visitor numbers (incl. monthly totals) are placeholders'),
  ('SRC_ENV_01', '한국환경공단_에어코리아_대기오염정보', 'AirKorea air pollution information', 'KECO / AirKorea', 'https://www.data.go.kr/data/15073861/openapi.do', 4, 'OFFICIAL_OPEN_DATA', 'fixtures/airkorea_sample.json (real API responses)', 'API called 2026-11-15 (getMsrstnAcctoRltmMesureDnsty); 5 Songdo stations x ~24 h; dataset page id not re-checked'),
  ('SRC_ENV_02', '한국환경공단_에어코리아_측정소정보', 'AirKorea monitoring station information', 'KECO / AirKorea', 'https://www.data.go.kr/data/15073877/openapi.do', 4, 'OFFICIAL_OPEN_DATA', 'fixtures/songdo_air_stations.csv (Songdo subset)', 'API called 2026-11-15 (getMsrstnList addr=인천): 43 stations, 5 inside the Songdo bbox; dataset page id not re-checked'),
  ('SRC_ENV_SYN', '송도 대기질 합성 측정값', 'Synthetic Songdo air-quality readings', 'Team (generator)', NULL, 4, 'SYNTHETIC_FIXTURE', 'Deterministic generator fixtures/environment_section.py', 'Readings for 2026-10-02 at the real station locations; not official data'),
  ('SRC_SAF_01', '인천광역시_소방서 현황(119안전센터)', 'Incheon fire stations and 119 safety centers', 'Incheon Fire', 'https://www.data.go.kr', 4, 'OFFICIAL_OPEN_DATA', 'Songdo safety stations fixture', 'Level from handbook; team must re-verify'),
  ('SRC_SAF_02', '인하대학교_사고대응 훈련 합성데이터', 'Synthetic incident response drill data', 'Inha University', NULL, 4, 'SYNTHETIC_FIXTURE', '10,000+ incident drill generator', 'Synthetic by design; never presented as official data')
